{
 "summary": "The main theorem `ehrhart_volume_inequality_for_sets` faithfully states Theorem 1.1: a compact, convex, full-dimensional S ⊂ ℝⁿ with barycenter 0 and interior lattice points exactly {0} has volume ≤ (n+1)ⁿ/n!. The sharpness side is broken: `simplexDilation` scales by (n+2) instead of (n+1), so `barycenter_centeredSimplex` and `normalizedVolume_centeredSimplex` are false as stated for n ≥ 1. `exists_centeredBody_sharp` does not use the broken definition and states the intended existence correctly.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ, with the product Lebesgue measure.", "standard_concept": "Euclidean space ℝⁿ with Lebesgue measure", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.integerPoint", "line": 12, "plain": "Casts an integer vector z ∈ ℤⁿ into ℝⁿ.", "standard_concept": "ℤⁿ ⊂ ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δₙ = {x ≥ 0, Σ xᵢ ≤ 1} = conv{0, e₁,…,eₙ}.", "standard_concept": "Δₙ = conv{0, e₁,…,eₙ}", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+2)·x − (1,…,1).", "standard_concept": "x ↦ (n+1)·x − (1,…,1), as in the paper's (n+1)Δₙ − (1,…,1)", "matches_standard": "no", "note": "The factor is n+2, not n+1. The image simplex then has barycenter (1/(n+1))·(1,…,1) and volume (n+2)ⁿ/n!."},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "Image of Δₙ under the (n+2)-dilation minus 1.", "standard_concept": "(n+1)Δₙ − (1,…,1)", "matches_standard": "no", "note": "Inherits the wrong scaling from `simplexDilation`. It is not centered at 0 and has the wrong volume."},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue measure of K as a real number (toReal).", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "The name suggests a normalization, but it is plain volume. toReal is harmless for compact K, which has finite measure."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "(1/vol K)·∫_K x dx.", "standard_concept": "barycenter (centroid) of K", "matches_standard": "yes", "note": "Junk values occur only if vol K = 0 or the integrand is non-integrable. Full-dimensional compact K avoids both."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "{z ∈ ℤⁿ : z ∈ int K}.", "standard_concept": "int(K) ∩ ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "Convex compact set with nonempty interior, barycenter 0, and interior lattice points exactly {0}.", "standard_concept": "hypotheses of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)ⁿ/n!.", "standard_concept": "(n+1)ⁿ/n!", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For every n, the image of Δₙ under x ↦ (n+2)x − 1 has barycenter 0. This is false for n ≥ 1; for n = 1 the barycenter is 1/2."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, the volume of that simplex equals (n+1)ⁿ/n!. It actually has volume (n+2)ⁿ/n!, so this is false; for n = 1 the volume is 3 versus 2."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0 there exists a compact convex full-dimensional body with barycenter 0, interior lattice points exactly {0}, and volume (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0, if S is compact, convex, has nonempty interior, has barycenter 0, and its interior lattice points are exactly {0}, then vol(S) ≤ (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A full-dimensional compact convex K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} satisfies vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark (after Thm 1.1)", "plain": "The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "The hypotheses and conclusion match. n > 0 is a harmless assumption."},
  {"paper_ref": "Sharpness remark", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "equivalent", "why": "It states existence of an extremal body without referencing the faulty simplex definition."},
  {"paper_ref": "Sharpness remark (explicit simplex: barycenter 0, volume)", "lean_theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "relation": "different", "why": "The Lean simplex uses the factor n+2, so the claim is false for n ≥ 1 rather than the paper's true claim."},
  {"paper_ref": "Sharpness remark (explicit simplex: volume)", "lean_theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "relation": "different", "why": "With the factor n+2 the volume is (n+2)ⁿ/n! ≠ (n+1)ⁿ/n!."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "high", "decl": "Ehrhart.simplexDilation", "line": 19, "paper_ref": "Sharpness remark after Theorem 1.1", "explanation": "The dilation uses (n+2) instead of (n+1). The paper's simplex is (n+1)Δₙ − 1, whose vertices sum to 0 in each coordinate. With n+2 the vertex coordinate sums are 1, so the barycenter is (1/(n+1))·1 ≠ 0. The volume is (n+2)ⁿ/n!, which differs from the sharp constant. The statements `barycenter_centeredSimplex` and `normalizedVolume_centeredSimplex` are therefore false for n ≥ 1 and cannot be faithful to the paper.", "polarity": "unclear", "probe_idea": "Prove `¬ (barycenter (centeredSimplex 1) = 0)` and `normalizedVolume (centeredSimplex 1) = 3`. Here centeredSimplex 1 = [-1, 2], with barycenter 1/2 and volume 3, versus sharpConstant 1 = 2."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "paper_ref": "Sharpness remark", "explanation": "This theorem is correct on its own but does not use `centeredSimplex`. The witness must be built from the correct (n+1)-scaled simplex, so the faulty definition does not affect this statement.", "polarity": "n/a", "probe_idea": null}
 ],
 "lint_verdicts": []
}
